insert into public.text_templates(kind, code, lang, field, body, source_ref, status) values
  ('task', 'T_SOW', 'vi', 'name', 'Gieo hạt / trồng cây', 'seed:v1', 'ai_unverified'),
  ('task', 'T_SOW', 'vi', 'steps', 'Dùng đất tơi xốp, thoát nước tốt, làm ẩm nhẹ trước.
Gieo hoặc đặt cây theo độ sâu ghi trên bao hạt, phủ một lớp đất mỏng.
Tưới phun sương nhẹ cho đất ẩm đều, đặt nơi sáng nhưng không nắng gắt.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_SOW', 'vi', 'why', 'Bắt đầu đúng cách giúp hạt nảy mầm đều và cây bén rễ tốt.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_SOW', 'en', 'name', 'Sow seeds / plant', 'seed:v1', 'ai_unverified'),
  ('task', 'T_SOW', 'en', 'steps', 'Use loose, well-draining soil and moisten it lightly first.
Sow or set the plant at the depth on the seed packet and cover with a thin layer of soil.
Mist gently until the soil is evenly damp and place in bright light without harsh sun.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_SOW', 'en', 'why', 'A good start helps seeds sprout evenly and roots establish.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRANSPLANT', 'vi', 'name', 'Chuyển cây ra chậu chính', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRANSPLANT', 'vi', 'steps', 'Tưới nhẹ cây con trước đó vài giờ để bầu đất dính chặt.
Nhấc cả bầu đất, giữ nguyên rễ, đặt vào chậu mới ở độ sâu bằng chậu cũ.
Lấp đất, nén nhẹ, tưới đẫm rồi để chỗ mát vài ngày.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRANSPLANT', 'vi', 'why', 'Chuyển vào buổi chiều mát giúp rễ ít bị sốc.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRANSPLANT', 'vi', 'safety', 'Nên đeo găng tay khi chạm vào nhựa cây hoặc đất đã bón phân.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRANSPLANT', 'en', 'name', 'Move to final pot', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRANSPLANT', 'en', 'steps', 'Water the seedling a few hours before so the root ball holds together.
Lift the whole root ball, keep roots intact and set it at the same depth in the new pot.
Fill in, press lightly, water well and keep in shade for a few days.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRANSPLANT', 'en', 'why', 'Transplanting in the cool afternoon reduces root shock.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRANSPLANT', 'en', 'safety', 'Wear gloves when handling sap or fertilized soil.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_REPOT', 'vi', 'name', 'Thay chậu / thay đất', 'seed:v1', 'ai_unverified'),
  ('task', 'T_REPOT', 'vi', 'steps', 'Chọn chậu lớn hơn một cỡ, có lỗ thoát nước.
Nhẹ nhàng lấy cây ra, gỡ bớt đất cũ và cắt rễ úng hoặc thâm nếu có.
Trồng lại bằng đất mới tơi xốp, tưới nhẹ rồi để chỗ mát vài ngày.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_REPOT', 'vi', 'why', 'Đất và chậu mới giúp rễ có chỗ phát triển và thoát nước tốt.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_REPOT', 'vi', 'safety', 'Nên đeo găng tay khi chạm vào nhựa cây hoặc đất đã bón phân.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_REPOT', 'en', 'name', 'Repot / refresh soil', 'seed:v1', 'ai_unverified'),
  ('task', 'T_REPOT', 'en', 'steps', 'Pick a pot one size larger with drainage holes.
Slide the plant out, loosen old soil and trim any soggy or dark roots.
Replant in fresh loose soil, water lightly and keep in shade for a few days.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_REPOT', 'en', 'why', 'Fresh soil and a roomier pot give roots space and better drainage.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_REPOT', 'en', 'safety', 'Wear gloves when handling sap or fertilized soil.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_HARDEN', 'vi', 'name', 'Cho cây làm quen nắng', 'seed:v1', 'ai_unverified'),
  ('task', 'T_HARDEN', 'vi', 'steps', 'Đưa cây ra chỗ nắng nhẹ vài giờ mỗi ngày.
Tăng dần thời gian phơi nắng trong vài ngày.
Theo dõi lá, nếu cháy mép thì lùi lại một bước.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_HARDEN', 'vi', 'why', 'Làm quen từ từ giúp cây không bị sốc nắng.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_HARDEN', 'en', 'name', 'Acclimate to sun', 'seed:v1', 'ai_unverified'),
  ('task', 'T_HARDEN', 'en', 'steps', 'Set the plant in gentle sun for a few hours a day.
Increase the time in the sun gradually over several days.
Watch the leaves; if edges scorch, step back.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_HARDEN', 'en', 'why', 'Gradual exposure prevents sunburn shock.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_THIN', 'vi', 'name', 'Tỉa cây con cho thưa', 'seed:v1', 'ai_unverified'),
  ('task', 'T_THIN', 'vi', 'steps', 'Chọn những cây khỏe nhất để giữ lại.
Dùng kéo cắt sát gốc cây yếu, tránh nhổ để không động rễ cây bên cạnh.
Giữ khoảng cách đủ để lá không chạm nhau.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_THIN', 'vi', 'why', 'Cây đủ chỗ sẽ lớn khỏe và ít bệnh hơn.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_THIN', 'en', 'name', 'Thin seedlings', 'seed:v1', 'ai_unverified'),
  ('task', 'T_THIN', 'en', 'steps', 'Pick the strongest seedlings to keep.
Snip weak ones at soil level instead of pulling, to protect neighbouring roots.
Leave enough space that leaves do not touch.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_THIN', 'en', 'why', 'Plants with room grow stronger and get fewer diseases.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_STAKE', 'vi', 'name', 'Dựng cọc đỡ cây', 'seed:v1', 'ai_unverified'),
  ('task', 'T_STAKE', 'vi', 'steps', 'Cắm cọc chắc cách gốc một đoạn để không đâm vào rễ.
Buộc thân vào cọc bằng dây mềm, buộc lỏng kiểu số 8.
Kiểm tra lại dây khi cây lớn thêm.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_STAKE', 'vi', 'why', 'Cọc giữ thân thẳng, quả không chạm đất.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_STAKE', 'en', 'name', 'Stake the plant', 'seed:v1', 'ai_unverified'),
  ('task', 'T_STAKE', 'en', 'steps', 'Push a sturdy stake in a little away from the base to avoid roots.
Tie the stem to it loosely with soft twine in a figure eight.
Re-check the ties as the plant grows.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_STAKE', 'en', 'why', 'Support keeps stems upright and fruit off the ground.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRELLIS', 'vi', 'name', 'Hướng dây leo lên giàn', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRELLIS', 'vi', 'steps', 'Nhẹ nhàng đưa ngọn dây leo về phía giàn.
Buộc lỏng bằng dây mềm nếu dây chưa tự bám.
Tỉa bớt tược quá dày để thoáng gió.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRELLIS', 'vi', 'why', 'Giàn giúp cây leo gọn, đón nắng và thông thoáng.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRELLIS', 'en', 'name', 'Guide vines onto the trellis', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRELLIS', 'en', 'steps', 'Gently turn the vine tips toward the trellis.
Tie loosely with soft twine if they do not cling on their own.
Thin overly dense shoots for airflow.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_TRELLIS', 'en', 'why', 'A trellis keeps vines tidy, sunny and airy.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MULCH', 'vi', 'name', 'Phủ gốc giữ ẩm', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MULCH', 'vi', 'steps', 'Phủ một lớp rơm, lá khô hoặc vỏ dừa mỏng quanh gốc.
Chừa một khoảng nhỏ sát thân để tránh thối gốc.
Bổ sung khi lớp phủ mục dần.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MULCH', 'vi', 'why', 'Lớp phủ giữ ẩm, hạn chế cỏ dại và giữ đất mát.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MULCH', 'en', 'name', 'Mulch the base', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MULCH', 'en', 'steps', 'Spread a thin layer of straw, dry leaves or coco husk around the base.
Leave a small gap next to the stem to prevent rot.
Top up as it breaks down.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MULCH', 'en', 'why', 'Mulch holds moisture, limits weeds and keeps soil cool.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_WATER', 'vi', 'name', 'Tưới nước', 'seed:v1', 'ai_unverified'),
  ('task', 'T_WATER', 'vi', 'steps', 'Kiểm tra đất: chọc ngón tay sâu khoảng 2 đốt, nếu khô thì tưới.
Tưới chậm quanh gốc cho nước thấm đều đến khi thấy nước chảy ra lỗ đáy chậu.
Đổ bỏ nước đọng ở đĩa lót chậu.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_WATER', 'vi', 'why', 'Tưới theo độ ẩm đất giúp tránh cả khô héo lẫn úng rễ.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_WATER', 'en', 'name', 'Water', 'seed:v1', 'ai_unverified'),
  ('task', 'T_WATER', 'en', 'steps', 'Check the soil: push a finger in about two knuckles; water if it is dry.
Water slowly around the base until it drains from the bottom holes.
Empty any water standing in the saucer.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_WATER', 'en', 'why', 'Watering by soil moisture avoids both wilting and root rot.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MIST', 'vi', 'name', 'Phun sương lá', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MIST', 'vi', 'steps', 'Phun sương nhẹ lên lá bằng nước sạch.
Làm vào buổi sáng để lá kịp khô trước tối.
Không phun khi lá đang đọng nước hoặc có đốm bệnh.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MIST', 'vi', 'why', 'Giữ không khí quanh cây đủ ẩm, nhất là trong phòng điều hòa.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MIST', 'en', 'name', 'Mist the leaves', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MIST', 'en', 'steps', 'Mist leaves lightly with clean water.
Do it in the morning so leaves dry before night.
Skip it when leaves are wet or show disease spots.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_MIST', 'en', 'why', 'Keeps the air around the plant humid, especially in air-conditioned rooms.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_CHECK_DRAINAGE', 'vi', 'name', 'Kiểm tra thoát nước', 'seed:v1', 'ai_unverified'),
  ('task', 'T_CHECK_DRAINAGE', 'vi', 'steps', 'Nâng chậu, xem lỗ đáy có bị nghẹt không.
Thông lỗ thoát nước, đổ bỏ nước đọng ở đĩa.
Nếu đất luôn sũng, xới nhẹ mặt đất cho thoáng.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_CHECK_DRAINAGE', 'vi', 'why', 'Thoát nước tốt là cách phòng úng rễ đơn giản nhất.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_CHECK_DRAINAGE', 'en', 'name', 'Check drainage', 'seed:v1', 'ai_unverified'),
  ('task', 'T_CHECK_DRAINAGE', 'en', 'steps', 'Lift the pot and check the bottom holes are not blocked.
Clear the holes and empty any standing water in the saucer.
If soil stays soggy, loosen the surface gently.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_CHECK_DRAINAGE', 'en', 'why', 'Good drainage is the simplest protection against root rot.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_FERT_ORGANIC', 'vi', 'name', 'Bón phân hữu cơ', 'seed:v1', 'ai_unverified'),
  ('task', 'T_FERT_ORGANIC', 'vi', 'steps', 'Dùng phân hữu cơ như phân trùn quế hoặc phân hữu cơ ủ hoai.
Rải mỏng quanh gốc, cách thân một chút rồi tưới nhẹ.
Với sản phẩm mua sẵn, làm đúng theo nhãn; không tự ý tăng lượng.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_FERT_ORGANIC', 'vi', 'why', 'Dinh dưỡng hữu cơ nhẹ nhàng giúp cây lớn đều và cải thiện đất.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_FERT_ORGANIC', 'vi', 'safety', 'Ưu tiên cách hữu cơ và an toàn trước; chỉ cân nhắc sản phẩm khác khi cách nhẹ nhàng không đủ.
Nếu dùng bất kỳ sản phẩm nào, hãy đọc kỹ nhãn và làm đúng hướng dẫn của nhà sản xuất. Ứng dụng không đưa ra liều lượng.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_FERT_ORGANIC', 'en', 'name', 'Feed with organic fertilizer', 'seed:v1', 'ai_unverified'),
  ('task', 'T_FERT_ORGANIC', 'en', 'steps', 'Use organic options such as worm castings or well-rotted compost.
Spread a thin layer around the base, a little away from the stem, then water lightly.
For store-bought products follow the label; never add extra.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_FERT_ORGANIC', 'en', 'why', 'Gentle organic feeding supports steady growth and improves the soil.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_FERT_ORGANIC', 'en', 'safety', 'Try organic and gentle options first; consider other products only if gentle options are not enough.
If you use any product, read the label and follow the manufacturer instructions. The app never gives doses.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_COMPOST_TOPDRESS', 'vi', 'name', 'Phủ phân ủ lên mặt đất', 'seed:v1', 'ai_unverified'),
  ('task', 'T_COMPOST_TOPDRESS', 'vi', 'steps', 'Xới nhẹ lớp đất mặt.
Rải một lớp mỏng phân ủ hoai hoặc phân trùn quế.
Tưới nhẹ để dinh dưỡng thấm dần.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_COMPOST_TOPDRESS', 'vi', 'why', 'Bổ sung dinh dưỡng chậm và giữ đất tơi xốp.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_COMPOST_TOPDRESS', 'vi', 'safety', 'Ưu tiên cách hữu cơ và an toàn trước; chỉ cân nhắc sản phẩm khác khi cách nhẹ nhàng không đủ.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_COMPOST_TOPDRESS', 'en', 'name', 'Top-dress with compost', 'seed:v1', 'ai_unverified'),
  ('task', 'T_COMPOST_TOPDRESS', 'en', 'steps', 'Loosen the top layer of soil.
Add a thin layer of well-rotted compost or worm castings.
Water lightly so nutrients seep in slowly.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_COMPOST_TOPDRESS', 'en', 'why', 'Adds slow-release nutrition and keeps soil loose.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_COMPOST_TOPDRESS', 'en', 'safety', 'Try organic and gentle options first; consider other products only if gentle options are not enough.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_EGGSHELL_ADD', 'vi', 'name', 'Thêm vỏ trứng nghiền', 'seed:v1', 'ai_unverified'),
  ('task', 'T_EGGSHELL_ADD', 'vi', 'steps', 'Rửa sạch, phơi khô vỏ trứng rồi nghiền thật mịn.
Rải mỏng quanh gốc và trộn nhẹ vào lớp đất mặt.
Tưới nhẹ; tác dụng đến chậm nên cần kiên nhẫn.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_EGGSHELL_ADD', 'vi', 'why', 'Vỏ trứng bổ sung canxi hữu cơ từ từ cho đất.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_EGGSHELL_ADD', 'vi', 'safety', 'Ưu tiên cách hữu cơ và an toàn trước; chỉ cân nhắc sản phẩm khác khi cách nhẹ nhàng không đủ.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_EGGSHELL_ADD', 'en', 'name', 'Add crushed eggshell', 'seed:v1', 'ai_unverified'),
  ('task', 'T_EGGSHELL_ADD', 'en', 'steps', 'Rinse and dry eggshells, then crush them to a fine powder.
Sprinkle thinly around the base and mix into the top soil.
Water lightly; the effect is slow so be patient.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_EGGSHELL_ADD', 'en', 'why', 'Eggshell slowly adds organic calcium to the soil.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_EGGSHELL_ADD', 'en', 'safety', 'Try organic and gentle options first; consider other products only if gentle options are not enough.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PRUNE', 'vi', 'name', 'Tỉa cành, lá', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PRUNE', 'vi', 'steps', 'Cắt bỏ lá vàng, cành khô, cành mọc chen vào trong.
Cắt chếch phía trên mắt lá, dùng kéo sạch.
Không tỉa quá nhiều một lần, giữ lại phần lớn lá xanh.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PRUNE', 'vi', 'why', 'Tỉa đúng giúp cây thông thoáng, ít sâu bệnh và ra chồi mới.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PRUNE', 'vi', 'safety', 'Dùng kéo hoặc dao sạch, sắc và cẩn thận khi cắt; lau cồn dụng cụ giữa các cây nếu có sâu bệnh.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PRUNE', 'en', 'name', 'Prune', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PRUNE', 'en', 'steps', 'Remove yellow leaves, dry branches and branches crowding the centre.
Cut at an angle just above a node with clean scissors.
Do not prune too much at once; keep most of the green leaves.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PRUNE', 'en', 'why', 'Proper pruning gives airflow, fewer pests and new shoots.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PRUNE', 'en', 'safety', 'Use clean, sharp scissors and cut carefully; wipe tools between plants if there is disease.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PINCH', 'vi', 'name', 'Bấm ngọn', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PINCH', 'vi', 'steps', 'Dùng tay hoặc kéo bấm bỏ phần ngọn trên cặp lá mới.
Bấm bỏ nụ hoa nếu cây chưa đủ lớn hoặc cần ra nhiều lá.
Có thể dùng phần ngọn vừa bấm làm rau.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PINCH', 'vi', 'why', 'Bấm ngọn làm cây phân nhánh, bụi và cho nhiều lá hơn.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PINCH', 'en', 'name', 'Pinch tips', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PINCH', 'en', 'steps', 'Pinch off the growing tip just above a new pair of leaves.
Remove flower buds if the plant is young or you want more leaves.
Use the pinched tips in the kitchen.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_PINCH', 'en', 'why', 'Pinching makes the plant branch and bush out with more leaves.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_DEADHEAD', 'vi', 'name', 'Cắt hoa tàn', 'seed:v1', 'ai_unverified'),
  ('task', 'T_DEADHEAD', 'vi', 'steps', 'Tìm những bông đã héo, thâm.
Cắt phía trên cặp lá khỏe gần nhất.
Bỏ hoa tàn vào thùng rác, không để dưới gốc.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_DEADHEAD', 'vi', 'why', 'Cắt hoa tàn giúp cây tập trung ra hoa mới và hạn chế nấm bệnh.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_DEADHEAD', 'vi', 'safety', 'Dùng kéo hoặc dao sạch, sắc và cẩn thận khi cắt; lau cồn dụng cụ giữa các cây nếu có sâu bệnh.', 'seed:v1', 'ai_unverified'),
  ('task', 'T_DEADHEAD', 'en', 'name', 'Remove spent flowers', 'seed:v1', 'ai_unverified'),
  ('task', 'T_DEADHEAD', 'en', 'steps', 'Look for faded or browning blooms.
